    int numPops = 0;
    if (descriptor.startsWith("(")) {
        int balance = 1;
        int i = 1;
        while (balance != 0) {
            if (descriptor.charAt(i) == '(') {
                balance++;
            } else if (descriptor.charAt(i) == ')') {
                balance--;
            }
            i++;
        }
        numPops = i - 2;
    } else {
        numPops = 1;
    }
    while (numPops > 0) {
        outputFrameStack.pop();
        numPops--;
    }
}
